def delivery_fee(amount):
    if amount >= 30000:
        return 0
    return 2500

class FeeLog:
    def __init__(self):
        self.fees = []

    def record(self, amount):
        fee = delivery_fee(amount)
        self.fees.append(fee)

log = FeeLog()
log.record(30000)
log.record(10000)
print(log.fees)
print(delivery_fee(50000))

def average(total, count):
    if count == 0:
        return None
    return total / count

class StudyLog:
    def __init__(self):
        self.minutes = []

    def add(self, minutes):
        self.minutes.append(minutes)

log = StudyLog()
log.add(10)
log.add(20)
print(log.minutes)
print(average(30, 2))
print(average(0, 0))

def result(score):
    if score >= 60:
        return "통과"
    return "다시 연습"

print(result(59))
print(result(60))

def fee(amount):
    if amount >= 20000:
        return 0
    return 2000

class Log:
    def __init__(self):
        self.costs = []

    def record(self, amount):
        self.costs.append(fee(amount))

log = Log()
log.record(20000)
log.record(19999)
print(log.costs)
